// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetAuthConfig Which sign-in options this server offers
	// (GET /auth/config)
	GetAuthConfig(ctx context.Context, request GetAuthConfigRequestObject) (GetAuthConfigResponseObject, error)
	// SignInDev Development-only sign-in by name (disabled unless DEV_LOGIN=1)
	// (POST /auth/dev)
	SignInDev(ctx context.Context, request SignInDevRequestObject) (SignInDevResponseObject, error)
	// SignInWithGoogle Sign in with a Google ID token (creates the account on first sign-in)
	// (POST /auth/google)
	SignInWithGoogle(ctx context.Context, request SignInWithGoogleRequestObject) (SignInWithGoogleResponseObject, error)
	// Logout End the current session
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// ListCards The signed-in player's collection (paged, filterable)
	// (GET /cards)
	ListCards(ctx context.Context, request ListCardsRequestObject) (ListCardsResponseObject, error)
	// GetHealth Liveness and database check
	// (GET /health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// GetCurrentLeaderboard This week's leaderboard (live)
	// (GET /leaderboard/current)
	GetCurrentLeaderboard(ctx context.Context, request GetCurrentLeaderboardRequestObject) (GetCurrentLeaderboardResponseObject, error)
	// GetLeaderboard A weekly season's leaderboard
	// (GET /leaderboard/{seasonId})
	GetLeaderboard(ctx context.Context, request GetLeaderboardRequestObject) (GetLeaderboardResponseObject, error)
	// GetMe The signed-in player's profile
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// MergeCards Merge two of your cards
	// (POST /merges)
	MergeCards(ctx context.Context, request MergeCardsRequestObject) (MergeCardsResponseObject, error)
	// ClaimDailyPack Open today's free pack (one per UTC day)
	// (POST /packs/daily/claim)
	ClaimDailyPack(ctx context.Context, request ClaimDailyPackRequestObject) (ClaimDailyPackResponseObject, error)
	// ListRecipes Recipes the signed-in player has discovered
	// (GET /recipes)
	ListRecipes(ctx context.Context, request ListRecipesRequestObject) (ListRecipesResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

